import {resolveComponentCurve} from './loss-models.js?v=2.5.4';
import {runProject,CATEGORIES} from './engine.js?v=2.5.4';
export const SENSITIVITY_PARAMETERS={vgsOn:'Gate-on Vgs',rgOn:'Turn-on gate resistance',rgOff:'Turn-off gate resistance',temperature:'Reference temperature',parallel:'Parallel device count',series:'Series device count',resistanceScale:'ESR / winding resistance',coreLossScale:'Core-loss characteristic',Rth:'Thermal resistance'};
export function sensitivityParameters(inst,c){const keys=['temperature','parallel','series'];if(inst?.type==='MOSFET'){if(c.gateType==='logic'&&c.enabled.includes('conduction'))keys.unshift('vgsOn');if(c.enabled.includes('on'))keys.push('rgOn');if(c.enabled.includes('off'))keys.push('rgOff');}if(['Capacitor','Inductor'].includes(inst?.type)&&c.enabled.includes('copper'))keys.push('resistanceScale');if(inst?.type==='Inductor'&&c.enabled.includes('core'))keys.push('coreLossScale');if(c.thermal.mode==='iterative')keys.push('Rth');return Object.fromEntries(keys.map(k=>[k,SENSITIVITY_PARAMETERS[k]]));}
export function sensitivityCoverage(inst,c,parameter){if(['series','parallel','resistanceScale','coreLossScale'].includes(parameter))return true;const dep=parameter==='vgsOn'?'Vgs':parameter.startsWith('rg')?'Rg':parameter==='temperature'||parameter==='Rth'?'Tj':null;const groups=parameter==='rgOn'?['on']:parameter==='rgOff'?['off']:Object.keys({...(inst.type==='MOSFET'?{channel:1,body:1,on:1,off:1,temperature:1}:inst.type==='Diode'?{forward:1,recovery:1}:inst.type==='Capacitor'?{esr:1}:{copper:1,core:1})});return groups.some(group=>{let curve;try{curve=resolveComponentCurve(c,group,inst.type);}catch{return false;}const category={channel:'conduction',temperature:'conduction',forward:'conduction',body:'body',on:'on',off:'off',recovery:'recovery',esr:'copper',copper:'copper',core:'core'}[group];if(!c.enabled.includes(category))return false;if(!curve||curve.dependencyPolicy?.[dep]?.enabled===false||(dep==='Tj'&&curve.temperatureIndependent))return false;return [curve.xName,curve.yName].some(k=>k===dep||(dep==='Tj'&&k==='T'))||(dep==='Tj'?['Tj','T']:[dep]).some(key=>new Set((curve.iterations||[]).map(it=>it.deps?.[key]).filter(Number.isFinite)).size>1);});}
export function sensitivityScenario(project,config,parameter,direction){if(!(parameter in SENSITIVITY_PARAMETERS))throw Error('Unknown sensitivity parameter');const p=structuredClone(project),inst=p.instances.find(i=>i.id===config.instanceId),c=inst?.candidates.find(c=>c.id===config.candidateId);if(!c)throw Error('Select a candidate in the chosen combination');const setting=config.perturbations?.[parameter],percent=Number(setting?.value??config.percent??2);if((!setting||setting.unit==='%')&&!(percent>0&&percent<50))throw Error('Sensitivity percentage must be between 0 and 50');if(setting&&!['%',...(parameter==='temperature'?['°C']:['parallel','series'].includes(parameter)?['devices']:[])].includes(setting.unit))throw Error('Unsupported perturbation unit for '+parameter);let before,after,unit='%',change;
 if(['resistanceScale','coreLossScale'].includes(parameter)){before=1;after=1+direction*percent/100;const group=parameter==='coreLossScale'?'core':inst.type==='Capacitor'?'esr':'copper',curve=resolveComponentCurve(c,group,inst.type);if(!curve)throw Error('No active characteristic for this loss');const quantity=parameter==='coreLossScale'?'Pv':'ESR';if(curve.constant!==undefined)curve.constant*=after;else for(const it of curve.iterations){const axis=curve.xName===quantity?'x':curve.yName===quantity?'y':null;if(!axis)throw Error('Characteristic does not provide '+quantity);it[axis]=it[axis].map(v=>v*after);}if(parameter==='resistanceScale'&&Number.isFinite(c.dcResistance))c.dcResistance*=after;change=direction*percent;}else if(parameter==='Rth'){before=c.thermal.Rth;if(!(before>0))throw Error('Baseline thermal resistance must be positive');after=before*(1+direction*percent/100);c.thermal.Rth=after;change=direction*percent;}else if(parameter==='temperature'){before=c.thermal.temperature;const step=setting?.unit==='%'?(before+273.15)*percent/100:Number(setting?.value??config.temperatureStep??5);if(!(step>0&&Number.isFinite(step)))throw Error('Temperature step must be positive');after=before+direction*step;c.thermal.temperature=after;unit=setting?.unit==='%'?'%':'°C';change=direction*(setting?.unit==='%'?percent:step);}
 else if(['parallel','series'].includes(parameter)){before=c[parameter];const step=setting?.unit==='%'?Math.round(before*percent/100):Number(setting?.value??1);if(!Number.isInteger(step)||step<1)throw Error('Perturbation must change the device count by at least one whole device; increase the percentage or use devices');after=before+direction*step;if(after<1)throw Error((parameter==='series'?'Series':'Parallel')+' count cannot fall below one');c[parameter]=after;c.totalCount=c.totalCount*after/before;if(!Number.isInteger(c.totalCount))throw Error('Replicated device count cannot be rescaled to an integer');change=100*(after/before-1);}
 else{if(parameter==='vgsOn'&&c.gateType!=='logic')throw Error('Gate-on Vgs sensitivity requires a logic gate waveform');before=c[parameter];if(!(Number.isFinite(before)&&before>0))throw Error('Baseline parameter must be positive');after=before*(1+direction*percent/100);c[parameter]=after;change=direction*percent;}
 return {project:p,before,after,change,unit,requested:setting?{...setting}:null};}
function metrics(result){if(!result.rows.length||result.rows.some(r=>!r.valid))return null;const count=result.rows.length;return {loss:result.rows.reduce((s,r)=>s+r.totalLoss,0)/count,efficiency:result.rows.reduce((s,r)=>s+r.efficiency,0)/count,categories:Object.fromEntries(CATEGORIES.map(k=>[k,result.rows.reduce((s,r)=>s+r.categories[k],0)/count]))};}
export function runSensitivity(project,config,progress=()=>{}){const p=structuredClone(project);for(const i of p.instances){const id=config.selection[i.id];i.candidates=i.candidates.filter(c=>c.id===id);if(!i.candidates.length)throw Error('Selected combination is no longer available');}if(config.waveformId)p.waveforms=p.waveforms.filter(w=>w.id===config.waveformId);const baseline=runProject(p),base=metrics(baseline);if(!base)throw Error('Sensitivity requires a complete valid baseline');const parameters=config.parameters||['vgsOn'],scenarios=[],total=parameters.length*2;let done=0;
 for(const parameter of parameters){if(!(parameter in SENSITIVITY_PARAMETERS))throw Error('Unknown sensitivity parameter');for(const direction of [-1,1]){try{const changed=sensitivityScenario(p,config,parameter,direction),result=runProject(changed.project),m=metrics(result),warnings=[...new Set(result.rows.flatMap(r=>r.devices.flatMap(d=>d.notes||[d.error])).filter(Boolean))];const target=p.instances.find(i=>i.id===config.instanceId),candidate=target.candidates[0],represented=sensitivityCoverage(target,candidate,parameter),zero=m&&Math.abs(m.loss-base.loss)<=1e-10*Math.max(1,Math.abs(base.loss));scenarios.push({parameter,label:SENSITIVITY_PARAMETERS[parameter],response:!m?'Scenario failed':zero?(represented?'No loss response at these operating points':'Dependency absent or disabled in the active characteristics; zero response is not evidence of physical insensitivity'):'Model response computed',dependencyRepresented:represented,categoryDelta:m?Object.fromEntries(CATEGORIES.map(k=>[k,m.categories[k]-base.categories[k]])):null,direction,requested:changed.requested,before:changed.before,after:changed.after,change:changed.change,unit:changed.unit,valid:!!m,meanLoss:m?.loss??null,lossChange:m&&base.loss!==0?100*(m.loss/base.loss-1):null,lossDelta:m?m.loss-base.loss:null,efficiencyDelta:m?m.efficiency-base.efficiency:null,elasticity:m&&base.loss!==0&&changed.unit==='%'&&changed.change!==0?(100*(m.loss/base.loss-1))/changed.change:null,categories:m?.categories,points:result.rows.map(r=>({waveformId:r.waveformId,vin:r.vin,vout:r.vout,outputPower:r.outputPower,valid:r.valid,totalLoss:r.totalLoss,baselineLoss:baseline.rows.find(b=>b.waveformId===r.waveformId)?.totalLoss})),warnings,errors:result.rows.flatMap(r=>r.reasons||[])});}catch(e){scenarios.push({parameter,label:SENSITIVITY_PARAMETERS[parameter],direction,requested:config.perturbations?.[parameter]||null,valid:false,errors:[e.message]});}progress(++done/total);}}
 return {perturbations:structuredClone(config.perturbations||{}),baseline:base,scenarios,instanceId:config.instanceId,candidateId:config.candidateId,combination:config.combination,operatingPoints:baseline.rows.length,createdAt:new Date().toISOString(),assumption:'One parameter at a time. Imported waveforms and frequency are held fixed. Series count changes per-device voltage and total device count; parallel count changes per-device current and total device count, assuming ideal sharing. These are model sensitivities, not a circuit re-simulation. Unrepresented dependencies can give zero sensitivity; extrapolation warnings must be reviewed.'};}
